{
  "name": "opencode-mathesis",
  "version": "0.7.1",
  "description": "Mathesis: probe, teach, practice and spaced repetition for opencode",
  "license": "AGPL-3.0-only",
  "type": "module",
  "author": "AlapinEnjoyer",
  "repository": {
    "type": "git",
    "url": "git+https://github.com/AlapinEnjoyer/mathesis.git"
  },
  "homepage": "https://github.com/AlapinEnjoyer/mathesis#readme",
  "bugs": {
    "url": "https://github.com/AlapinEnjoyer/mathesis/issues"
  },
  "keywords": [
    "opencode",
    "opencode-plugin",
    "learning",
    "spaced-repetition",
    "fsrs",
    "tutor"
  ],
  "engines": {
    "bun": ">=1.3.14",
    "opencode": ">=2.2.1 <3"
  },
  "exports": {
    ".": "./src/server.ts",
    "./tui": "./dist/tui.js",
    "./gui-experimental": "./dist/gui-experimental.cjs",
    "./rpc": "./src/rpc.ts"
  },
  "files": [
    "dist",
    "src",
    "LICENSE",
    "NOTICE.md",
    "README.md"
  ],
  "scripts": {
    "test": "bun test",
    "typecheck": "tsc --noEmit",
    "build": "bun scripts/build-tui.ts && vite build",
    "prepare": "bun run build",
    "prepack": "bun run build",
    "prepublishOnly": "bun run typecheck && bun test"
  },
  "dependencies": {
    "ts-fsrs": "^6.0.0",
    "yaml": "^2.9.1"
  },
  "peerDependencies": {
    "@opencode/plugin": ">=2.2.1 <3",
    "@opentui/core": ">=0.7.0",
    "@opentui/solid": ">=0.7.0",
    "solid-js": ">=1.9.0"
  },
  "devDependencies": {
    "@opencode/plugin": "2.2.1",
    "@opencode/theme": "2.2.1",
    "@opentui/core": "0.7.0",
    "@opentui/solid": "0.7.0",
    "@types/bun": "1.3.14",
    "solid-js": "1.9.12",
    "typescript": "7.0.2",
    "vite": "^8.3.6",
    "vite-plugin-solid": "^2.11.15"
  },
  "peerDependenciesMeta": {
    "@opentui/core": {
      "optional": true
    },
    "@opentui/solid": {
      "optional": true
    },
    "solid-js": {
      "optional": true
    }
  }
}
